/** Ship DSH's pinned, dependency-free search engine inside the existing worker bundle. */
import { createRequire } from "node:module";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
const require = createRequire(import.meta.url);
const manifest = require.resolve("@deepseek-ai/dsh-file-reference-local/package.json");
if (JSON.parse(readFileSync(manifest, "utf8")).version !== "0.2.0-rc.2") throw new Error("Revalidate remote file completion before upgrading DSH");
let source = readFileSync(require.resolve("@deepseek-ai/dsh-file-reference-local/search"), "utf8");
for (const line of [
  "import { lstat, readdir } from 'node:fs/promises';",
  "import { isAbsolute, join, relative, resolve, sep } from 'node:path';",
  "export { activeAtToken, formatFileMention } from '@deepseek-ai/dsh-file-reference/grammar';",
]) {
  if (source.split(line).length !== 2) throw new Error(`DSH file search import changed: ${line}`);
  source = source.replace(line, "");
}
source = source.replace(/^export /gm, "").replace(/\n\/\/# sourceMappingURL=search\.js\.map\s*$/, "");
const license = readFileSync(join(dirname(manifest), "LICENSE"), "utf8").trimEnd();
const names = ["WorkspaceFileSearch", "DEFAULT_FILE_SEARCH_MAX_RESULTS", "DEFAULT_FILE_SEARCH_MAX_ENTRIES", "DEFAULT_FILE_SEARCH_EXCLUDED_DIRECTORIES"];
const begin = "// BEGIN vendored DSH file search", end = "// END vendored DSH file search";
const file = new URL("../workspace-files.mjs", import.meta.url);
const target = readFileSync(file, "utf8");
if (target.split(begin).length !== 2 || target.split(end).length !== 2) throw new Error("Missing managed DSH search region");
const region = `${begin}\n/*\n * Generated by dsh-product/sync-file-search.mjs from\n * @deepseek-ai/dsh-file-reference-local@0.2.0-rc.2 /search.\n * Search logic is unchanged; imports and exports are adapted for this bundle.\n *\n${license.split("\n").map((line) => line ? ` * ${line}` : " *").join("\n")}\n */\nconst DshFileSearch = (() => {\n${source.trimEnd()}\nreturn { ${names.join(", ")} };\n})();\n${end}`;
const updated = target.slice(0, target.indexOf(begin)) + region + target.slice(target.indexOf(end) + end.length);
if (process.argv.includes("--check")) {
  if (updated !== target) throw new Error("Run node dsh-product/sync-file-search.mjs to sync the native file search engine");
} else if (updated !== target) writeFileSync(file, updated);
process.stdout.write("DSH native file search engine verified\n");
